// Writes (or, with --check, verifies) the golden files of the deterministic construct suite: for every fixture under
// construct-suite/, the type TypeScript 7.1's checker gives prop `p` of each row's component (the exported `Row`, or
// the components a fixture lists), normalized as src/oracle.ts normalizes it, and the facts about the prop both lanes
// are held to (`Facts`). One program holds all fixtures.
import { existsSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { join, relative } from 'node:path'
import { SyntaxKind } from 'typescript-beta/ast'
import { API, SymbolFlags } from 'typescript-beta/sync'
import { exportAt, propsTypeOf } from './checker-components.ts'
import { listFixtures, PROP, type Facts, type Fixture, type Golden } from './construct-suite.ts'
import { checkerNormalizer } from './oracle-checker.ts'

const suite = realpathSync(join(import.meta.dirname, '..', 'construct-suite'))
const check = process.argv.includes('--check')

const fixtures = listFixtures(suite)
if (fixtures.length === 0) throw new Error(`no fixtures under ${suite}`)

const api = new API({ cwd: suite })
// `parseConfigFile`, not options by hand: the 7.1 beta's server panics on string-valued enum options (src/oracle.ts).
const { options } = api.parseConfigFile(join(suite, 'tsconfig.json'))
const program = api.createProgram([...new Set(fixtures.map((f) => f.file))], options)
const { checker } = program.getProject()
const norm = checkerNormalizer(checker)

/** The union a declaration writes for its type: the type node itself, or the type of the non-generic alias it names. */
function writtenUnion(typeNode: any): any[] | null {
  let node = typeNode
  if (node?.kind === SyntaxKind.TypeReference) {
    const alias = checker.getSymbolAtLocation(node.typeName)
    const declaration: any =
      alias && alias.flags & SymbolFlags.TypeAlias ? alias.declarations?.[0]?.resolve() : undefined
    if (declaration?.kind === SyntaxKind.TypeAliasDeclaration && declaration.typeParameters === undefined) {
      node = declaration.type
    }
  }
  return node?.kind === SyntaxKind.UnionType ? [...node.types] : null
}

function factsOf(prop: any): Facts {
  const tags: Record<string, string> = {}
  for (const tag of checker.getJsDocTagsOfSymbol(prop)) tags[tag.name] = (tag.text ?? '').trim()
  const declaration: any = prop.declarations?.[0]?.resolve()
  const parent = declaration?.parent
  const members = writtenUnion(declaration?.type)
  return {
    description: checker.getDocumentationCommentOfSymbol(prop),
    tags,
    default: tags.default ?? tags.defaultValue ?? null,
    required: (prop.flags & SymbolFlags.Optional) === 0,
    parent:
      parent?.kind === SyntaxKind.InterfaceDeclaration
        ? { name: parent.name.text, file: relative(suite, realpathSync(parent.getSourceFile().fileName)) }
        : null,
    order: members && members.map((member) => norm(checker.getTypeFromTypeNode(member))),
  }
}

function capture(fixture: Fixture): Golden {
  const moduleSymbol = checker.getSymbolOfSourceFile(fixture.file)
  const exported = moduleSymbol && exportAt(checker, moduleSymbol, fixture.exportPath)
  if (!exported) throw new Error(`${fixture.id}: no export ${fixture.exportPath.join('.')}`)
  const propsType = propsTypeOf(checker, exported)
  const prop = propsType && checker.getPropertyOfType(propsType, PROP)
  if (!prop) throw new Error(`${fixture.id}: ${fixture.component} has no prop ${PROP}`)
  const type = checker.getTypeOfSymbol(prop)
  return { checker: norm(type), text: checker.typeToString(type), facts: factsOf(prop) }
}

// A unique-symbol key is named `__@tag@<symbol id>` and the id depends on the other files in the program, so adding a
// fixture would change an unrelated golden. Keep the name, drop the id.
const stableSymbolIds = (json: string) => json.replaceAll(/__@(\w+)@\d+/g, '__@$1')

const stale: string[] = []
for (const fixture of fixtures) {
  const text = `${stableSymbolIds(JSON.stringify(capture(fixture), null, 2))}\n`
  const current = existsSync(fixture.golden) ? readFileSync(fixture.golden, 'utf8') : undefined
  if (current === text) continue
  stale.push(fixture.id)
  if (!check) writeFileSync(fixture.golden, text)
}
program.dispose()
api.close()

if (check && stale.length > 0) {
  console.error(
    `golden files out of date (run pnpm --filter caliper-docgen-oracle construct:capture):\n  ${stale.join('\n  ')}`,
  )
  process.exit(1)
}
console.error(`${fixtures.length} fixtures, ${stale.length} ${check ? 'differ' : 'written'}`)
// The deterministic construct suite's pure half (apps/oracle/construct-suite/README.md): which fixtures exist, the verdict
// one of Caliper's props earns against its golden, and the check of the expectations file. Nothing here runs the checker
// or Caliper, so tests/construct-suite.test.ts can pin it without either.
import { existsSync, readdirSync, readFileSync, realpathSync } from 'node:fs'
import { join, relative } from 'node:path'
import { caliperNorm } from './caliper-norm.ts'
import { pathOfExport, exportPathKey, type ComponentExport } from './component-join.ts'
import type { PropType } from '../../../packages/napi/index.d.ts'
import { compare, type Norm } from './oracle-compare.ts'
import { isAgreement, ROW_VERDICTS, type RowVerdict } from './vocabulary.ts'

/** The prop every fixture states its type through. */
export const PROP = 'p'

/** What `--check` and the test read back from `<name>.golden.json`. */
export interface Golden {
  /** The checker's type of prop `p`, normalized by src/oracle-checker.ts. */
  checker: Norm
  /** `checker.typeToString` of the same type, for the reader of a diff. */
  text: string
  /** What else the checker states about prop `p`, compared on every row in both lanes (`factDifferences`). */
  facts: Facts
}

/** The facts about a prop besides its type that both lanes are held to, as the checker (and its AST) states them. */
export interface Facts {
  /** `getDocumentationComment`. */
  description: string
  /** `getJsDocTags`, by name, the last of a repeated tag winning, each text trimmed. */
  tags: Record<string, string>
  /** The text of its `@default` (or `@defaultValue`) tag; null with neither. A fixture writes no code default. */
  default: string | null
  required: boolean
  /** react-docgen-typescript's `parent`: the interface its first declaration is a member of, by name and by file
   * relative to the suite; null for a member of a type literal. */
  parent: { name: string; file: string } | null
  /** The members of the union its declaration writes, in written order (through a non-generic alias it names), each
   * normalized as `checker` is; null when it writes no union. */
  order: Norm[] | null
}

export type FactName = keyof Facts

export const FACTS: FactName[] = ['description', 'tags', 'default', 'required', 'parent', 'order']

/** One row: a component of a fixture file. A file holds one row (`Row`, exported as `Row`) unless it lists its
 * components (`componentsOf`). */
export interface Fixture {
  /** `<family>/<NN>-<slug>`, or `<family>/<NN>-<slug>#<component>` in a file of several components: the row id the
   * expectations file keys on. */
  id: string
  /** The fixture's absolute path. */
  file: string
  /** The golden's absolute path, next to the fixture: `<NN>-<slug>.golden.json`, or `<NN>-<slug>.<component>.golden.json`. */
  golden: string
  /** The component's display name in Caliper's output. */
  component: string
  /** How the module exports it: the export name (`default` for the default export), then the properties of the export
   * a sub-component is attached to (`['default', 'Item']` for `Menu.Item = Item; export default Menu`). */
  exportPath: string[]
 * `opaque with marker`: Caliper said it did not evaluate the type. A `wrong` prop stays wrong with or without a marker. */
export function rowVerdict(prop: { type: PropType; degradedBy?: unknown } | undefined, golden: Golden): RowVerdict {
  if (prop === undefined) return 'missing'
  const verdict = compare(caliperNorm(prop.type), golden.checker)
  const marked = Array.isArray(prop.degradedBy) && prop.degradedBy.length > 0
  return marked && verdict === 'less precise' ? 'opaque with marker' : verdict
}

/** The facts of Caliper's prop that differ from the golden's, in `FACTS` order. A prop Caliper did not list has no
 * facts to compare (its verdict is `missing`). `suite` is the suite's real path, which a golden's `parent.file` is
 * relative to. A union's order differs when two of Caliper's members that each state one written member stand in the
 * other order; members it does not state one for are the type verdict's business. */
export function factDifferences(prop: any | undefined, golden: Golden, suite: string): FactName[] {
  if (prop === undefined) return []
  const { facts } = golden
  const caliperParent = prop.parent
    ? { name: prop.parent.name, file: relative(suite, onDisk(prop.parent.fileName)) }
    : null
  const same: Record<FactName, boolean> = {
    description: (prop.description ?? '') === facts.description,
    tags: sameRecord(prop.tags ?? {}, facts.tags),
    default: (prop.defaultValue?.value ?? null) === facts.default,
    required: prop.required === facts.required,
    parent: JSON.stringify(caliperParent) === JSON.stringify(facts.parent),
    order: facts.order === null || keepsOrder(prop.type, facts.order),
  }
  return FACTS.filter((fact) => !same[fact])
}

/** The real path of a file that exists; any other path as it is, so it differs from the golden's instead of throwing. */
const onDisk = (file: string): string => (existsSync(file) ? realpathSync(file) : file)

function sameRecord(a: Record<string, string>, b: Record<string, string>): boolean {
  const keys = Object.keys(a).toSorted()
  return JSON.stringify(keys) === JSON.stringify(Object.keys(b).toSorted()) && keys.every((key) => a[key] === b[key])
}

/** Whether Caliper's union states the written members it has in their written order. */
function keepsOrder(type: any, written: Norm[]): boolean {
  if (type?.kind !== 'union' || !Array.isArray(type.members)) return true
  const members = type.members.map((member: any) => caliperNorm(member))
  const positions = written
    .map((member) => members.findIndex((mine: Norm) => isAgreement(compare(mine, member))))
    .filter((position) => position >= 0)
  return positions.every((position, index) => index === 0 || position > positions[index - 1]!)
}

export interface Expectation {
  /** The verdicts the row may have; the test fails on any other. */
  verdicts: RowVerdict[]
  /** Why Caliper falls short of the checker here. Present exactly on a documented gap. */
  gap?: string
  /** The facts (`factDifferences`) Caliper may state differently from the golden, each with the reason. The test fails
   * on any other difference, and on a listed fact that no longer differs. */
  facts?: Partial<Record<FactName, string>>
  /** checker-expectations.json only: why the checker path's answer is accepted although its verdict ranks below the
   * structural path's for the same row (see `againstStructural` in src/construct-checker-run.ts). */
  improvement?: string
}

/** Problems with the expectations against the fixtures; empty when they agree. */
export function expectationProblems(ids: string[], rows: Record<string, Expectation>): string[] {
  const problems: string[] = []
  for (const id of ids) {
    const row = rows[id]
    if (row === undefined) {
      problems.push(`${id}: no entry in expectations.json`)
      continue
    }
    if (!Array.isArray(row.verdicts) || row.verdicts.length === 0) {
      problems.push(`${id}: "verdicts" must list at least one verdict`)

