"""Tally a baseline trace: union props order.rs reordered (by where the prop is declared) and structural defaults (by
whether the extractor's code default or the checker's @default tag also has them). usage: tally.py <trace>"""
import sys
from collections import Counter

orders, defaults, code = [], [], {}
for line in open(sys.argv[1], encoding='utf-8', errors='replace'):
    parts = line.rstrip('\n').split('\t')
    if parts[0] == 'ORDER' and len(parts) == 8:
        orders.append(parts[1:])
    elif parts[0] == 'DEFAULT' and len(parts) == 6:
        defaults.append(parts[1:])
    elif parts[0] == 'CODE' and len(parts) == 4:
        code.setdefault((parts[1], parts[2]), set()).update(parts[3].split(','))

unions = len(orders)
changed = [o for o in orders if o[3] == 'true']
where = Counter()
for file, display, prop, _, has_structural, parent_file, parent_name in changed:
    if parent_file == '-':
        where['no parent (type literal or mapped)'] += 1
    elif 'node_modules' in parent_file:
        where['parent in a dependency'] += 1
    elif parent_file == file:
        where['parent in the component file'] += 1
    else:
        where['parent in another project file'] += 1
print(f'union props merged {unions}, reordered by the structural order {len(changed)}')
for key, count in where.most_common():
    print(f'  {key}: {count}')
unique = {(o[5], o[6], o[2]) for o in changed}
print(f'  distinct declarations reordered: {len(unique)}')

kinds = Counter()
for file, display, prop, value, tag in defaults:
    has_code = prop in code.get((file, display), set())
    tag = tag.strip('"')
    if has_code:
        kinds['code default (extractor)'] += 1
    elif tag != '-' and tag.strip("'\"") == value.strip('"').strip("'\"") or (tag != '-' and tag == value.strip('"')):
        kinds['@default tag the checker also gives'] += 1
    elif tag != '-':
        kinds['@default tag, checker text differs'] += 1
    else:
        kinds['neither (structural only)'] += 1
print(f'props with a structural default {len(defaults)}')
for key, count in kinds.most_common():
    print(f'  {key}: {count}')

