"""Print prop `p` of the construct rows whose golden has an order fact. usage: rows.py <extract json> <suite dir>"""
import json
import sys
from pathlib import Path

doc = json.loads(Path(sys.argv[1]).read_text())
suite = Path(sys.argv[2])


def flat(component):
    props = component['props']
    if isinstance(props, dict):
        return props
    merged = {}
    for set_id in props:
        merged.update(doc['propSets'][set_id])
    return merged


def short(t):
    k = t.get('kind')
    if k == 'union':
        return ' | '.join(short(m) for m in t['members'])
    if k in ('stringLiteral', 'numberLiteral', 'boolLiteral'):
        return json.dumps(t.get('value'))
    if k == 'named':
        return 'N:' + t.get('name', '?')
    return k


by_file = {}
for key, component in doc['components'].items():
    by_file.setdefault(component['filePath'], []).append(component)
for golden in sorted(suite.rglob('*.golden.json')):
    facts = json.loads(golden.read_text())['facts']
    if facts['order'] is None and facts['default'] is None:
        continue
    fixture = golden.with_name(golden.name.split('.')[0] + '.tsx')
    for component in by_file.get(str(fixture.resolve()), []):
        prop = flat(component).get('p')
        if prop is None:
            continue
        prop = doc['props'][prop]
        print(f"{golden.relative_to(suite)}: {short(prop['type'])}  default={prop.get('defaultValue')}")

