    /// Do not load the type declarations props reference from installed packages
    #[arg(long, conflicts_with = "load_dependencies")]
    pub no_load_dependencies: bool,

    /// Which inherited sources to list as one inherited layer of names instead of prop by prop: large ambient ones
    /// (DOM and ARIA attributes, style systems) from loaded dependencies by default; a dependency's own API is listed unless it declares more than 200 props
    #[arg(long, value_enum)]
    pub collapse_inherited_props: Option<CollapseInheritedPropsArg>,

    /// Experimental: ask TypeScript 7.1's `tsc --api` (or `tsrs`) for every component's props in one program and wait
    /// for the answer, which replaces the structural one prop by prop; the structural result stands wherever the
    /// checker cannot answer (off by default)
    #[arg(long)]
    pub experimental_semantic_types: bool,

    /// The checker binary `--experimental-semantic-types` runs (`tsc` or `tsrs`), instead of the nearest
    /// `node_modules/typescript/bin/tsc` or `node_modules/tsrs/bin/tsrs`
    #[arg(long, requires = "experimental_semantic_types")]
    pub tsc_path: Option<String>,

    /// With `--experimental-semantic-types`: how long the checker may take to start or to answer any one request, in
    /// milliseconds, before the run takes the structural result with one warning
    #[arg(long, requires = "experimental_semantic_types", default_value_t = DEFAULT_SEMANTIC_TIMEOUT_MS)]
    pub semantic_timeout_ms: u64,
}

/// `--semantic-timeout-ms` when not given: ADR 0026's proposed 10 s. A hung checker is caught that fast, and it bounds
/// each request, not the run: a 938-component Chakra and MUI program answers in 15 to 17 s in all within it.
pub const DEFAULT_SEMANTIC_TIMEOUT_MS: u64 = 10_000;
    let options = build_options(BuildOptionsArgs {
        src: &args.src,
        cache_dir: args.cache_dir.as_deref(),
        no_cache: args.no_cache,
        html_attributes,
        config_path,
        extra_builtins: &args.extra_builtins,
        load_dependencies: args.load_dependencies,
        no_load_dependencies: args.no_load_dependencies,
        collapse_inherited_props: args.collapse_inherited_props.map(Into::into),
    })?;
    let mut options = options;
    if args.experimental_semantic_types {
        options.experimental_semantic_types = true;
    }
    if let Some(path) = &args.tsc_path {
        options.semantic_tsc_path = Some(path.into());
    }

    let pb = if !quiet && !args.json {
        let pb = ProgressBar::new_spinner();
        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
        pb.set_message("Extracting...");
        pb.enable_steady_tick(std::time::Duration::from_millis(80));
        Some(pb)
    } else {
        None
    };

    let mut output = caliper_docgen_core::pipeline::extract(&options);
    if options.experimental_semantic_types {
        apply_semantic_backend(&options, std::time::Duration::from_millis(args.semantic_timeout_ms), &mut output);
    }

    if let Some(pb) = pb {
        pb.finish_and_clear();
    }

    // --json ignores --out/--format — see ExtractArgs::json's doc comment.
        no_cache: false,
        html_attributes: None,
        extra_builtins: vec![],
        include_unexported: false,
        json,
        load_dependencies: false,
        no_load_dependencies: false,
        collapse_inherited_props: None,
        experimental_semantic_types: false,
        tsc_path: None,
        semantic_timeout_ms: crate::DEFAULT_SEMANTIC_TIMEOUT_MS,
    }
}

