        PropType::Function { .. } => Some(MemberKind::Function),
        PropType::Callable { .. } => Some(MemberKind::Callable),
        PropType::Object(_) => Some(MemberKind::Object),
        PropType::Array(_) => Some(MemberKind::Array),
