"""Default and union-order differences between two checker runs. usage: compare.py <base json> <other json> [examples]"""
import json
import sys
from collections import Counter
from pathlib import Path

base = json.loads(Path(sys.argv[1]).read_text())
other = json.loads(Path(sys.argv[2]).read_text())
show = int(sys.argv[3]) if len(sys.argv) > 3 else 5


def flat(doc, component):
    props = component['props']
    if isinstance(props, dict):
        ids = props
    else:
        ids = {}
        for set_id in props:
            ids.update(doc['propSets'][set_id])
    return {name: doc['props'][i] for name, i in ids.items()}


def key(t):
    return json.dumps(t, sort_keys=True)


counts = Counter()
examples = {}
for ckey, component in base['components'].items():
    if ckey not in other['components']:
        continue
    a, b = flat(base, component), flat(other, other['components'][ckey])
    for name in a.keys() & b.keys():
        pa, pb = a[name], b[name]
